mapper.select:
SELECT

FROM News a WHERE 1 = 1

    AND a.category LIKE CONCAT('%',#{category}, '%')


    AND a.title LIKE CONCAT('%',#{title}, '%')


    AND a.summary LIKE CONCAT('%',#{summary}, '%')


    AND a.topicImage LIKE CONCAT('%',#{topicImage}, '%')


    AND a.content LIKE CONCAT('%',#{content}, '%')


    AND a.keyword LIKE CONCAT('%',#{keyword}, '%')


    AND a.isBanner = #{isBanner}


    AND a.isFixed = #{isFixed}


    AND a.state = #{state}


    AND a.viewNum = #{viewNum}


    AND a.favoriteNum = #{favoriteNum}


    AND a.likeNum = #{likeNum}


    AND a.commentNum = #{commentNum}


    AND a.shareNum = #{shareNum}


    AND a.lng LIKE CONCAT('%',#{lng}, '%')


    AND a.lat LIKE CONCAT('%',#{lat}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.createName LIKE CONCAT('%',#{createName}, '%')


    AND a.updateTime = #{updateTime}


    AND a.publishTime = #{publishTime}


    AND a.publishName LIKE CONCAT('%',#{publishName}, '%')
